function start(which='quick'){mode=which;const seed=mode==='daily'?hash(dayKey()):crypto.getRandomValues(new Uint32Array(1))[0];run=newRun(seed);rng=randomSeed(seed);lane=1;bus.position.x=0;bus.rotation.set(0,0,0);spawnClock=0;rowIndex=0;countTime=2.5;hitFlash=0;state='countdown';clearItems();$('home').classList.add('hidden');$('results').classList.add('hidden');$('pauseOverlay').classList.add('hidden');$('hud').classList.remove('hidden');$('countdown').classList.remove('hidden');$('touchControls').classList.remove('hidden');$('gameHint').classList.remove('hidden');$('modeLabel').textContent=mode==='daily'?tr('DAILY CHAOS','כאוס יומי'):tr('QUICK RUN','סיבוב מהיר');arena.classList.add('playing');$('toast').classList.remove('visible');updateHud();canvas.focus({preventScroll:true});tone(330,.12);}
