function finish(){state='results';run.ended=true;const won=run.seats>=61;const newBest=run.peak>best;if(newBest){best=run.peak;save('cc-best',best);$('best').textContent=best;}$('hud').classList.add('hidden');$('touchControls').classList.add('hidden');$('gameHint').classList.add('hidden');$('toast').classList.remove('visible');$('results').classList.remove('hidden');$('resultEyebrow').textContent=newBest?tr('A NEW PERSONAL BEST','שיא אישי חדש'):mode==='daily'?tr('DAILY CHAOS · ','הכאוס היומי · ')+dayKey():tr('THE RESULTS ARE IN','התוצאות הגיעו');$('resultTitle').textContent=won?tr('Coalition secured!','יש קואליציה!'):run.seats===0?tr('Government dissolved.','הממשלה התפזרה.'):tr('Another election?','שוב בחירות?');$('resultJoke').textContent=won?tr('You did it. Now agree on where to order lunch.','הצלחתם. עכשיו תסכימו מאיפה להזמין צהריים.'):run.peak>=61?tr('You had a majority. Then somebody read the group chat.','היה לכם רוב. ואז מישהו קרא את הקבוצה.'):tr('So close to power. So familiar. Run it back.','כל כך קרוב לשלטון. כל כך מוכר. עוד סיבוב?');$('resultSeats').textContent=run.seats;$('resultBest').textContent=run.peak;$('resultHits').textContent=run.hits;$('resultTime').textContent=Math.floor(run.held)+'s';$('share').querySelector('[data-i18n]').textContent=text[lang].share;$('again').focus({preventScroll:true});tone(won?880:160,.4);if(won)burst('#fbd659',65);}
function update(dt){elapsed+=dt;const playing=state==='running';const idle=state==='home';menuBlend=THREE.MathUtils.damp(menuBlend,idle?1:0,3.7,dt);const menuPos=mobile?new THREE.Vector3(18,21,28):new THREE.Vector3(23,21,30);const playPos=mobile?new THREE.Vector3(0,12,22):new THREE.Vector3(0,14,25);camera.position.copy(playPos.lerp(menuPos,menuBlend));const target=mobile?new THREE.Vector3(0,0,-6).lerp(new THREE.Vector3(-1,0,-1),menuBlend):new THREE.Vector3(0,0,-14).lerp(new THREE.Vector3(-8,0,-8),menuBlend);camera.lookAt(target);
if(idle){bus.position.x=0;bus.rotation.y=-.1;bus.position.y=reducedMotion?0:Math.sin(elapsed*2)*.035;}
if(state==='countdown'){countTime-=dt;$('countdown').textContent=countTime>.6?Math.ceil(countTime-.5):tr('GO!','יאללה!');if(countTime<=0){state='running';$('countdown').classList.add('hidden');tone(760,.16);}}
if(playing){tick(run,dt);bus.position.x=THREE.MathUtils.damp(bus.position.x,(lane-1)*3.2,15,dt);const tilt=THREE.MathUtils.clamp(((lane-1)*3.2-bus.position.x)*-.07,-.15,.15);bus.rotation.z=THREE.MathUtils.damp(bus.rotation.z,reducedMotion?0:tilt,12,dt);bus.rotation.y=THREE.MathUtils.damp(bus.rotation.y,0,10,dt);bus.position.y=reducedMotion?0:Math.sin(elapsed*20)*.018;const speed=14+run.time*.2;laneMarks.forEach(m=>{m.position.z+=speed*dt;if(m.position.z>27)m.position.z-=165;});scenery.forEach(g=>{g.position.z+=speed*dt;if(g.position.z>24)g.position.z-=144;});wheels.forEach(w=>w.rotation.x-=speed*dt*1.3);spawnClock-=dt;if(spawnClock<=0){for(const spec of courseRow(rng,rowIndex))addItem(spec.type,spec.lane,-63,spec.variant);rowIndex++;spawnClock+=1.3;}
for(const item of items){item.mesh.position.z+=speed*dt;if(!item.passed&&item.mesh.position.z>=3){item.passed=true;if(Math.abs(item.mesh.position.x-bus.position.x)<1.35){item.mesh.visible=false;hit(item);if(state!=='running')break;}}}
if(run.time>6)$('gameHint').classList.add('hidden');if(run.time>=DURATION&&state==='running')finish();updateHud();}
for(let i=items.length-1;i>=0;i--){const item=items[i];if(item.mesh.position.z>14){scene.remove(item.mesh);items.splice(i,1);}else if(item.type!=='hazard'&&state!=='paused'){item.mesh.rotation.y=Math.sin(elapsed*1.8+item.z)*.25;item.mesh.position.y=reducedMotion?0:Math.sin(elapsed*3+item.z)*.12;}}
if(state!=='paused'){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=10*dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.x+=dt*5;p.mesh.rotation.z+=dt*4;if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1);}}toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('visible');hitFlash=Math.max(0,hitFlash-dt);bus.visible=hitFlash>0?Math.floor(hitFlash*20)%2===0:true;}renderer.render(scene,camera);}
function frame(time){const dt=Math.min((time-last)/1000||0,.05);last=time;update(dt);animId=requestAnimationFrame(frame);}animId=requestAnimationFrame(frame);
$('loading').classList.add('hidden');$('play').disabled=false;$('daily').disabled=false;
$('play').onclick=()=>start();$('daily').onclick=()=>start('daily');$('again').onclick=()=>start(mode);$('resultHome').onclick=goHome;$('quit').onclick=goHome;$('pause').onclick=pause;$('resume').onclick=resume;$('left').onpointerdown=e=>{e.preventDefault();steer(-1);};$('right').onpointerdown=e=>{e.preventDefault();steer(1);};$('language').onclick=()=>{lang=lang==='en'?'he':'en';save('cc-lang',lang);translate();};$('sound').onclick=()=>{sound=!sound;setSound();tone(620,.1);};
let pointerStart=null;canvas.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x;if(Math.abs(dx)>24){steer(dx>0?1:-1);pointerStart={x:e.clientX,y:e.clientY};}});canvas.addEventListener('pointerup',()=>pointerStart=null);canvas.addEventListener('pointercancel',()=>pointerStart=null);
document.addEventListener('keydown',e=>{if($('info').open)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Escape','a','d','A','D','p','P'].includes(e.key)&&['running','countdown','paused'].includes(state)){e.preventDefault();if(e.repeat)return;if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')steer(-1);else if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')steer(1);else if([' ','Escape','p','P'].includes(e.key)){if(state==='paused')resume();else pause();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('blur',pause);
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(animId);pause();$('error').classList.remove('hidden');$('errorText').textContent=tr('The graphics connection was interrupted. Reload to start a fresh run.','החיבור הגרפי הופסק. טענו מחדש כדי להתחיל סיבוב חדש.');});
let returnFocus=null;function info(kind){pause();returnFocus=document.activeElement;if(kind==='help')$('infoContent').innerHTML=tr('<span class="eyebrow">A 61-SECOND CRASH COURSE</span><h2>How to run the country.<br>Well, the bus.</h2><ol><li><b>Steer between three lanes.</b> Swipe, tap the arrow buttons, or use ← → / A D.</li><li><b>Collect blue chairs.</b> Each adds 3 seats. Every fifth consecutive pickup adds 6!</li><li><b>Dodge red scandals.</b> They cost 8 seats and reset your streak.</li><li><b>Grab a falafel shield.</b> It absorbs one scandal. Shields don’t stack.</li><li><b>Finish with 61+ seats.</b> You start with 15; hold your majority until the 61-second run ends. Zero seats ends it early.</li></ol><p>Press Space or Esc to pause. Daily Chaos uses the same course for everyone, resetting at midnight in Jerusalem. Best scores stay on this device.</p>','<span class="eyebrow">קורס מזורז ב־61 שניות</span><h2>איך מנהלים מדינה.<br>כלומר, אוטובוס.</h2><ol><li><b>זזים בין שלושה נתיבים.</b> מחליקים, מקישים על החצים או משתמשים בחצי המקלדת.</li><li><b>אוספים כיסאות כחולים.</b> כל כיסא מוסיף 3 מנדטים. כל איסוף חמישי ברצף מוסיף 6!</li><li><b>מתחמקים משערוריות אדומות.</b> הן מורידות 8 מנדטים ומאפסות את הרצף.</li><li><b>לוקחים מגן פלאפל.</b> הוא סופג שערורייה אחת. אי אפשר לצבור מגנים.</li><li><b>מסיימים עם 61 מנדטים לפחות.</b> מתחילים עם 15. מחזיקים רוב עד סוף 61 השניות. אפס מנדטים מסיים את הסיבוב מוקדם.</li></ol><p>רווח או Esc משהים את המשחק. הכאוס היומי זהה לכולם ומתחדש בחצות לפי שעון ירושלים. השיאים נשמרים במכשיר הזה.</p>');else $('infoContent').innerHTML=tr('<span class="eyebrow">REAL MATH. RIDICULOUS BUS.</span><h2>Why 61?</h2><p>Israel’s Knesset has <b>120 seats</b>, so 61 is an absolute majority. Coalition-building is the inspiration for this game. Actual government formation follows parliamentary confidence procedures; this is an arcade simplification, not a civics simulator.</p><p>Parties need at least <b>3.25% of valid votes</b> to participate in seat allocation. Seats are distributed proportionally among qualifying lists.</p><p>We’re poking fun at political chaos, coalition bargaining, and election fatigue—not asking you to vote for anyone. The bus, scandals, bonuses, and results are fictional.</p><p><a href="https://main.knesset.gov.il/en/mk/pages/elections.aspx" target="_blank" rel="noopener noreferrer">Learn about elections on the Knesset website ↗</a></p>','<span class="eyebrow">חשבון אמיתי. אוטובוס מגוחך.</span><h2>למה 61?</h2><p>בכנסת יש <b>120 מושבים</b>, ולכן 61 הם רוב מוחלט. הרכבת קואליציה היא ההשראה למשחק. הקמת ממשלה כפופה להליכי אמון בכנסת; המשחק הוא פישוט ארקייד, לא סימולטור אזרחות.</p><p>רשימה צריכה לקבל לפחות <b>3.25% מהקולות הכשרים</b> כדי להשתתף בחלוקת המנדטים, המחולקים באופן יחסי בין הרשימות שעברו את אחוז החסימה.</p><p>אנחנו צוחקים על הבלגן הפוליטי, המיקוח הקואליציוני ועייפות הבחירות — בלי לבקש להצביע לאף אחד. האוטובוס, השערוריות והתוצאות בדיוניים.</p><p><a href="https://main.knesset.gov.il/mk/elections/Pages/default.aspx" target="_blank" rel="noopener noreferrer">על הבחירות באתר הכנסת ↗</a></p>');$('info').showModal();}
$('help').onclick=()=>info('help');$('about').onclick=()=>info('about');$('closeInfo').onclick=()=>$('info').close();$('info').addEventListener('close',()=>returnFocus?.focus());$('info').addEventListener('click',e=>{const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close();});
$('share').onclick=async()=>{const url=new URL(location.href);url.search='';url.searchParams.set('challenge',String(run.seats));if(mode==='daily')url.searchParams.set('daily',dayKey());const shareText=tr(`🚌 COALITION CHAOS\n${run.seats}/120 seats. ${run.hits} scandals. ${Math.floor(run.held)}s holding a majority.\n${run.seats>=61?'I formed a government. Your turn.':'My coalition fell apart. Can you get to 61?'}`,`🚌 כאוס קואליציוני\n${run.seats}/120 מנדטים. ${run.hits} שערוריות. ${Math.floor(run.held)} שניות עם רוב.\n${run.seats>=61?'הקמתי ממשלה. תורכם.':'הקואליציה שלי התפרקה. תצליחו להגיע ל־61?'}`);try{if(navigator.share){await navigator.share({title:'Coalition Chaos — Road to 61',text:shareText,url:url.href});}else{await navigator.clipboard.writeText(shareText+'\n'+url.href);$('share').querySelector('[data-i18n]').textContent=tr('Challenge copied! Paste it in the chat.','האתגר הועתק! הדביקו אותו בקבוצה.');}}catch(e){if(e.name==='AbortError')return;$('infoContent').replaceChildren();const h=document.createElement('h2');h.textContent=tr('Copy your challenge','העתיקו את האתגר');const textarea=document.createElement('textarea');textarea.value=shareText+'\n'+url.href;textarea.style.cssText='width:100%;height:160px;font:14px/1.5 sans-serif';textarea.readOnly=true;$('infoContent').append(h,textarea);$('info').showModal();textarea.select();}};
const params=new URLSearchParams(location.search);challengeTarget=Math.max(0,Math.min(120,Number(params.get('challenge'))||0));if(challengeTarget){setTimeout(()=>showToast(tr(`Group chat challenge: beat ${challengeTarget} seats!`,`אתגר מהקבוצה: עברו ${challengeTarget} מנדטים!`)),900);if(params.get('daily')===dayKey())$('daily').querySelector('[data-i18n="sameCourse"]').textContent=tr('Your friend’s course','המסלול של החבר');}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_coalition_game',title:'Read current game',description:'Read the current mode, game phase, seats, time remaining and local personal best.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({phase:state,mode,seats:run.seats,secondsRemaining:Math.ceil(DURATION-run.time),best})},{name:'start_coalition_run',title:'Start a coalition run',description:'Start a quick or daily run from the home or results screen. Replaces the displayed result with a new countdown.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['quick','daily']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['quick','daily'].includes(input.mode)||Object.keys(input).length!==1)throw new Error('Provide only mode: quick or daily.');if(!['home','results'].includes(state))throw new Error('Finish or quit the current run first.');start(input.mode);return {phase:state,mode,seats:run.seats};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
